  timezone: string; // IANA zone anchoring every Hours entry
  hours: AffiliateHour[]; // open time ranges (wall-clock in Timezone)
  details: string; // markdown
  logo: string; // root-relative web path (images/affiliate_logos/...)
  screenshot: string; // root-relative web path (images/affiliate_images/...)
  embed_color: string; // Discord embed accent, "#rrggbb" ("" = brand default)
  discord_link: string; // optional Discord invite/link
  carrd_link: string; // optional Carrd (or other) site link
  sort_order: number /* int */; // manual drag order (ascending)
  created_at: string;
